import type { LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";

// Reusable premium empty state (spec §52) — never a bare "nothing here".
export function EmptyState({
  icon: Icon,
  title,
  description,
  action,
  className,
}: {
  icon: LucideIcon;
  title: string;
  description: string;
  action?: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col items-center justify-center rounded-2xl border border-dashed border-border bg-muted/60 px-6 py-12 text-center", className)}>
      <span className="flex h-14 w-14 items-center justify-center rounded-full bg-white text-brand-navy shadow-sm">
        <Icon className="h-6 w-6" strokeWidth={1.5} />
      </span>
      <h3 className="mt-4 text-sm font-bold text-foreground">{title}</h3>
      <p className="mt-1.5 max-w-sm text-sm text-muted-foreground">{description}</p>
      {action && <div className="mt-5">{action}</div>}
    </div>
  );
}
